// Test-only fixed clients, temporary database, no payment.
import {spawn} from 'node:child_process';import {createInterface} from 'node:readline';import {pathToFileURL} from 'node:url';import {mkdtemp,rm,writeFile} from 'node:fs/promises';import {tmpdir} from 'node:os';import {join} from 'node:path';import {once} from 'node:events';import assert from 'node:assert/strict';
const sdk=process.env.SDK_SOURCE_DIR,clients=process.env.CLIENT_SOURCE_DIR;
const {AuthSocketClient}=await import('@bsv/authsocket-client');const {MessageBoxClient}=await import(pathToFileURL(`${clients}/packages/messaging/message-box-client/src/MessageBoxClient.ts`));
const {default:ProtoWallet}=await import(pathToFileURL(`${sdk}/src/wallet/ProtoWallet.ts`));const {default:PrivateKey}=await import(pathToFileURL(`${sdk}/src/primitives/PrivateKey.ts`));
const dir=await mkdtemp(join(tmpdir(),'messagebox-live-'));let child,exited;const sockets=[];
try {
 const key=join(dir,'key'),config=join(dir,'config.json');await writeFile(key,'0'.repeat(63)+'3\n',{mode:0o600});await writeFile(config,JSON.stringify({bind:'127.0.0.1:0',dataDir:dir,identityKeyFile:key,freeBoxes:['inbox'],enableWebSockets:true}));
 child=spawn(process.env.MESSAGEBOX_SERVER,[config],{stdio:['ignore','pipe','inherit']});exited=once(child,'exit');const lines=createInterface({input:child.stdout})[Symbol.asyncIterator]();const first=await Promise.race([lines.next(),exited.then(([code,signal])=>({early:{code,signal}}))]);assert.ok(!first.early&&!first.done,'runtime did not start');const ready=JSON.parse(first.value),host=`http://${ready.address}`,server=ready.identityKey;
 function wallet(n){const w=new ProtoWallet(new PrivateKey(n));w.createAction=async()=>{throw Error('Payments disabled')};return w;}
 function wait(socket,event){return new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error(`${event} timeout`)),8000);socket.on(event,data=>{clearTimeout(timer);resolve(data)});});}
 async function connect(n){const identity=new PrivateKey(n).toPublicKey().toString(),w=wallet(n),socket=AuthSocketClient(host,{wallet:w,expectedServerIdentityKey:server,managerOptions:{transports:['websocket'],forceNew:true,reconnection:false},onError:(error,context)=>console.error('authsocket error',error,context)});sockets.push(socket);const authenticated=wait(socket,'authenticationSuccess');socket.on('connect',()=>socket.emit('authenticated',{identityKey:identity}));assert.deepEqual(await authenticated,{status:'success'});return {socket,identity,w};}
 const alice=await connect(2),bob=await connect(4),bobUnjoined=await connect(4),eve=await connect(5),room=`${bob.identity}-inbox`;let bobCount=0,unjoinedCount=0,eveCount=0;bob.socket.on(`sendMessage-${room}`,()=>bobCount++);bobUnjoined.socket.on(`sendMessage-${room}`,()=>unjoinedCount++);eve.socket.on(`sendMessage-${room}`,()=>eveCount++);
 const forbidden=wait(eve.socket,'joinFailed');eve.socket.emit('joinRoom',room);assert.equal((await forbidden).code,'ERR_WEBSOCKET_ROOM_NOT_OWNED');
 const joined=wait(bob.socket,'joinedRoom');bob.socket.emit('joinRoom',room);assert.deepEqual(await joined,{roomId:room});
 const ack=wait(alice.socket,`sendMessageAck-${room}`),push=wait(bob.socket,`sendMessage-${room}`);
 alice.socket.emit('sendMessage',{roomId:room,message:{messageId:'ws-live-test',recipient:bob.identity,body:'hello live'}});
 assert.deepEqual(await ack,{status:'success',messageId:'ws-live-test'});assert.deepEqual(await push,{sender:alice.identity,messageId:'ws-live-test',body:'hello live'});
 const receiver=new MessageBoxClient({host,walletClient:bob.w,serverIdentityKeysByHost:{[host]:server}});
 const invalid=wait(alice.socket,'messageFailed');alice.socket.emit('sendMessage',{roomId:`${alice.identity}-inbox`,message:{messageId:'bad-room',recipient:bob.identity,body:'bad'}});assert.equal((await invalid).reason,'Room does not match canonical recipient and message box');
 const noBody=wait(alice.socket,'messageFailed');alice.socket.emit('sendMessage',{roomId:room,message:{messageId:'empty-body',recipient:bob.identity,body:''}});assert.equal((await noBody).reason,'Invalid message body');
 const badKey=wait(alice.socket,'messageFailed');alice.socket.emit('sendMessage',{roomId:room,message:{messageId:'bad-key',recipient:'bad-key',body:'x'}});assert.equal((await badKey).reason,'Invalid recipient identity key');
 const badId=wait(alice.socket,'messageFailed');alice.socket.emit('sendMessage',{roomId:room,message:{messageId:' spaced ',recipient:bob.identity,body:'x'}});assert.equal((await badId).reason,'Invalid message ID');
 const duplicate=wait(alice.socket,`sendMessageAck-${room}`);alice.socket.emit('sendMessage',{roomId:room,message:{messageId:'ws-live-test',recipient:bob.identity,body:'duplicate'}});assert.equal((await duplicate).code,'ERR_DUPLICATE_MESSAGE');
 await receiver.setMessageBoxPermission({messageBox:'inbox',recipientFee:-1,sender:alice.identity},host);const blocked=wait(alice.socket,`sendMessageAck-${room}`);alice.socket.emit('sendMessage',{roomId:room,message:{messageId:'blocked-live',recipient:bob.identity,body:'blocked'}});assert.equal((await blocked).code,'ERR_DELIVERY_BLOCKED');
 await receiver.setMessageBoxPermission({messageBox:'inbox',recipientFee:1,sender:alice.identity},host);const paid=wait(alice.socket,`sendMessageAck-${room}`);alice.socket.emit('sendMessage',{roomId:room,message:{messageId:'paid-live',recipient:bob.identity,body:'paid'}});assert.equal((await paid).code,'ERR_PAYMENT_NOT_IMPLEMENTED');
 await receiver.setMessageBoxPermission({messageBox:'inbox',recipientFee:0,sender:alice.identity},host);const left=wait(bob.socket,'leftRoom');bob.socket.emit('leaveRoom',room);await left;
 const afterLeave=wait(alice.socket,`sendMessageAck-${room}`);alice.socket.emit('sendMessage',{roomId:room,message:{messageId:'after-leave',recipient:bob.identity,body:'later'}});assert.equal((await afterLeave).status,'success');await new Promise(resolve=>setTimeout(resolve,300));assert.equal(bobCount,1);assert.equal(unjoinedCount,0);assert.equal(eveCount,0);
 const messages=await receiver.listMessagesLite({messageBox:'inbox'});assert.equal(messages.length,2);assert.deepEqual(messages.map(x=>x.messageId),['ws-live-test','after-leave']);assert.equal(messages[0].body,'hello live');assert.equal(messages[1].body,'later');
 for(const socket of sockets)socket.disconnect();child.kill('SIGINT');const [code]=await exited;assert.equal(code,0);child=undefined;
 console.log('Fixed clients: WS send, recipient isolation, failure paths, leave, and durable HTTP listing passed with test keys; no payment.');
} finally {for(const socket of sockets)socket.disconnect();if(child&&child.exitCode===null&&child.signalCode===null){child.kill('SIGKILL');await exited.catch(()=>{});}await rm(dir,{recursive:true,force:true});}
